Mutex_AC					CMutex;	typedef CMPQueue_AC					CQueue;	typedef CMPSemaphore_AC				CSemaphore;	typedef CTempMPMutex_AC				CTempMutex;	typedef CTempMPQueue_AC				CTempQueue;	typedef CTempMPSemaphore_AC			CTempSemaphore;	typedef CMutex::CWhileSynchronized	CWhileSynchronized;	typedef CYielder_AC					CYielder;	//--------------------------------------------------------------------------------	// Constructors, destructor, and assignment	//--------------------------------------------------------------------------------	CMPThread_AC();		// default constructor	CMPThread_AC(const CMPThread_AC& source);		// copy constructor	virtual ~CMPThread_AC();		// Destructor	void operator delete(void* ptr);		// Hand off deletion to the toolbox safe remote context. 	//--------------------------------------------------------------------------------	// Running	//--------------------------------------------------------------------------------	virtual CThread_AC* Start();	virtual MPTaskOptions GetMPTaskOptions() const;	operator MPTaskID() const { return fTaskID; }	virtual bool IsAlive() const;		// Returns true if the thread or task has not been terminated.	virtual bool IsCurrent() const;		// return true if the thread handle represents the current thread.	static MPTaskID Current();	static void Yield();		// Allows other threads time to execute.	virtual void Suspend();		// Suspends this thread.  Must be called from within the thread (e.g., Run).		// Must be awakened by another thread by calling CThreadRunner_AC's Resume method.			virtual void Resume();		// Resumes the execution of this thread if the thread stopped itself by 		// calling Suspend.			virtual void Join();		// Calls RequestShutdown and blocks the calling thread until the		// thread terminates.					virtual OSStatus GetResult(Duration timeout = kDurationImmediate);	//--------------------------------------------------------------------------------	// Utilities	//--------------------------------------------------------------------------------#if qDebug	#define FailIf(status) DebugFailIf((status),  __FILE__, __LINE__ )	static void DebugFailIf(OSStatus status, const char* inFile, short inLine);#else	static void FailIf(OSStatus status);#endif	static void ProgramBreak(ConstStr255Param msg);		// this accepts a pascal string.	static void ProgramBreak(const char* format, ...);		// this accepts printf style arguments.	static void ProgramBreak(const char* format, va_list args);		// this accepts var arguments.	//--------------------------------------------------------------------------------	// Private	//--------------------------------------------------------------------------------private:	static OSStatus EntryPoint(void* parameter);	//--------------------------------------------------------------------------------	// Data	//--------------------------------------------------------------------------------protected:	MPTaskID			fTaskID;	// ID for the MP task represented by this context.	CTempSemaphore		fLock;		// Lock used for suspending the context.	CQueue				fTermination;};#endif // qWantsMP#endif	// __CMPThread_AC__